28	// Grouped dependencies for clarity and easier mocking
29	export interface CommandContext {
30	  // Invocation properties for when commands are called.
31	  invocation?: {
32	    /** The raw, untrimmed input string from the user. */
33	    raw: string;
34	    /** The primary name of the command that was matched. */
35	    name: string;
36	    /** The arguments string that follows the command name. */
37	    args: string;
38	  };
39	  // Core services and configuration
40	  services: {
41	    // TODO(abhipatel12): Ensure that config is never null.
42	    config: Config | null;
43	    settings: LoadedSettings;
44	    git: GitService | undefined;
45	    logger: Logger;
46	  };
47	  // UI state and history management
48	  ui: {
49	    /** Adds a new item to the history display. */
50	    addItem: UseHistoryManagerReturn['addItem'];
51	    /** Clears all history items and the console screen. */
52	    clear: () => void;
53	    /**
54	     * Sets the transient debug message displayed in the application footer in debug mode.
55	     */
56	    setDebugMessage: (message: string) => void;
57	    /** The currently pending history item, if any. */
58	    pendingItem: HistoryItemWithoutId | null;
59	    /**
60	     * Sets a pending item in the history, which is useful for indicating
61	     * that a long-running operation is in progress.
62	     *
63	     * @param item The history item to display as pending, or `null` to clear.
64	     */
65	    setPendingItem: (item: HistoryItemWithoutId | null) => void;
66	    /**
67	     * Loads a new set of history items, replacing the current history.
68	     *
69	     * @param history The array of history items to load.
70	     * @param postLoadInput Optional text to set in the input buffer after loading history.
71	     */
72	    loadHistory: (history: HistoryItem[], postLoadInput?: string) => void;
73	    /** Toggles a special display mode. */
74	    toggleCorgiMode: () => void;
75	    toggleDebugProfiler: () => void;
76	    toggleVimEnabled: () => Promise<boolean>;
77	    reloadCommands: () => void;
78	    openAgentConfigDialog: (
79	      name: string,
80	      displayName: string,
81	      definition: AgentDefinition,
82	    ) => void;
83	    extensionsUpdateState: Map<string, ExtensionUpdateStatus>;
84	    dispatchExtensionStateUpdate: (action: ExtensionUpdateAction) => void;
85	    addConfirmUpdateExtensionRequest: (value: ConfirmationRequest) => void;
86	    /**
87	     * Sets a confirmation request to be displayed to the user.
88	     *
89	     * @param value The confirmation request details.
90	     */
91	    setConfirmationRequest: (value: ConfirmationRequest) => void;
92	    removeComponent: () => void;
93	    toggleBackgroundShell: () => void;
94	    toggleShortcutsHelp: () => void;
95	  };
96	  // Session-specific data
97	  session: {
98	    stats: SessionStatsState;
99	    /** A transient list of shell commands the user has approved for this session. */
100	    sessionShellAllowlist: Set<string>;
101	  };
102	  // Flag to indicate if an overwrite has been confirmed
103	  overwriteConfirmed?: boolean;
104	}
105	
106	/** The return type for a command action that results in the app quitting. */
107	export interface QuitActionReturn {
108	  type: 'quit';
109	  messages: HistoryItem[];
110	}
111	
112	/**
113	 * The return type for a command action that needs to open a dialog.
114	 */
115	export interface OpenDialogActionReturn {
116	  type: 'dialog';
117	  props?: Record<string, unknown>;
118	
119	  dialog:
120	    | 'help'
121	    | 'auth'
122	    | 'theme'
123	    | 'editor'
124	    | 'privacy'
125	    | 'settings'
126	    | 'sessionBrowser'
127	    | 'model'
128	    | 'agentConfig'
129	    | 'permissions';
130	}
131	
132	/**
133	 * The return type for a command action that needs to pause and request
134	 * confirmation for a set of shell commands before proceeding.
135	 */
136	export interface ConfirmShellCommandsActionReturn {
137	  type: 'confirm_shell_commands';
138	  /** The list of shell commands that require user confirmation. */
139	  commandsToConfirm: string[];
140	  /** The original invocation context to be re-run after confirmation. */
141	  originalInvocation: {
142	    raw: string;
143	  };
144	}
145	
146	export interface ConfirmActionReturn {
147	  type: 'confirm_action';
148	  /** The React node to display as the confirmation prompt. */
149	  prompt: ReactNode;
150	  /** The original invocation context to be re-run after confirmation. */
151	  originalInvocation: {
152	    raw: string;
153	  };
154	}
155	
156	export interface OpenCustomDialogActionReturn {
157	  type: 'custom_dialog';
158	  component: ReactNode;
159	}
160	
161	/**
162	 * The return type for a command action that specifically handles logout logic,
163	 * signaling the application to explicitly transition to an unauthenticated state.
164	 */
165	export interface LogoutActionReturn {
166	  type: 'logout';
167	}
168	
169	export type SlashCommandActionReturn =
170	  | CommandActionReturn<HistoryItemWithoutId[]>
171	  | QuitActionReturn
172	  | OpenDialogActionReturn
173	  | ConfirmShellCommandsActionReturn
174	  | ConfirmActionReturn
175	  | OpenCustomDialogActionReturn
176	  | LogoutActionReturn;
177	
178	export enum CommandKind {
179	  BUILT_IN = 'built-in',
180	  FILE = 'file',
181	  MCP_PROMPT = 'mcp-prompt',
182	  AGENT = 'agent',
183	}
184	
185	// The standardized contract for any command in the system.
186	export interface SlashCommand {
187	  name: string;
188	  altNames?: string[];
189	  description: string;
190	  hidden?: boolean;
191	
192	  kind: CommandKind;
193	
194	  /**
195	   * Controls whether the command auto-executes when selected with Enter.
196	   *
197	   * If true, pressing Enter on the suggestion will execute the command immediately.
198	   * If false or undefined, pressing Enter will autocomplete the command into the prompt window.
199	   */
200	  autoExecute?: boolean;
201	
202	  // Optional metadata for extension commands
203	  extensionName?: string;
204	  extensionId?: string;
205	
206	  // The action to run. Optional for parent commands that only group sub-commands.
207	  action?: (
208	    context: CommandContext,
209	    args: string, // TODO: Remove args. CommandContext now contains the complete invocation.
210	  ) =>
211	    | void
212	    | SlashCommandActionReturn
213	    | Promise<void | SlashCommandActionReturn>;
214	
215	  // Provides argument completion (e.g., completing a tag for `/chat resume <tag>`).
216	  completion?: (
217	    context: CommandContext,
218	    partialArg: string,
219	  ) => Promise<string[]> | string[];
220	
221	  /**
222	   * Whether to show the loading indicator while fetching completions.
223	   * Defaults to true. Set to false for fast completions to avoid flicker.
224	   */
225	  showCompletionLoading?: boolean;
226	
227	  subCommands?: SlashCommand[];
228	}
