206	    } catch (error: unknown) {
207	      coreEvents.emitFeedback(
208	        'error',
209	        `[FileCommandLoader] Failed to parse TOML file ${filePath}:`,
210	        error instanceof Error ? error.message : String(error),
211	      );
212	      return null;
213	    }
214	
